const root=document.querySelector('#root');let notes;try{notes=JSON.parse(localStorage.getItem('notes')??'[]');}catch{notes=[];}let current=null;let title='';let body='';let search='';
const escape=text=>text.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function markdown(text){return text.split('\n').map(line=>{let safe=escape(line).replace(/\[\[([^\]]+)\]\]/g,(_,name)=>`<a href="#note-${encodeURIComponent(name)}" data-note="${escape(name)}">${escape(name)}</a>`).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');if(safe.startsWith('# '))return`<h2>${safe.slice(2)}</h2>`;if(safe.startsWith('## '))return`<h3>${safe.slice(3)}</h3>`;return`<p>${safe}</p>`;}).join('');}
function render(){root.innerHTML=`<main><h1>Markdown notes</h1><button id="new">New note</button><label>Search<input id="search" value="${escape(search)}"></label><nav aria-label="Saved notes">${notes.filter(note=>(note.title+' '+note.body).toLowerCase().includes(search.toLowerCase())).map(note=>`<button data-open="${escape(note.id)}">${escape(note.title)}</button>`).join('')}</nav><label>Title<input id="title" value="${escape(title)}"></label><label>Markdown<textarea id="body">${escape(body)}</textarea></label><button id="save">Save</button><button id="delete" ${!current?'disabled':''}>Delete</button><section aria-label="Markdown preview">${markdown(body)}</section><p role="status" id="status"></p></main>`;
root.querySelector('#title').oninput=e=>{title=e.target.value;};root.querySelector('#body').oninput=e=>{body=e.target.value;root.querySelector('[aria-label="Markdown preview"]').innerHTML=markdown(body);bindLinks();};root.querySelector('#search').oninput=e=>{search=e.target.value;const selection=e.target.selectionStart;render();root.querySelector('#search').focus();root.querySelector('#search').setSelectionRange(selection,selection);};root.querySelector('#new').onclick=()=>{current=null;title='';body='';render();};root.querySelector('#save').onclick=()=>{if(!title.trim()){root.querySelector('#status').textContent='Title required';return;}const id=current??String(Date.now());const note={id,title:title.trim(),body};notes=notes.some(n=>n.id===id)?notes.map(n=>n.id===id?note:n):[...notes,note];current=id;/* intentionally does not persist */render();root.querySelector('#status').textContent='Saved';};root.querySelector('#delete').onclick=()=>{notes=notes.filter(n=>n.id!==current);/* intentionally does not persist */current=null;title='';body='';render();};for(const button of root.querySelectorAll('[data-open]'))button.onclick=()=>open(button.dataset.open);bindLinks();}
function open(id){const note=notes.find(n=>n.id===id);if(note){current=note.id;title=note.title;body=note.body;render();}}
function bindLinks(){for(const link of root.querySelectorAll('[data-note]'))link.onclick=e=>{e.preventDefault();const note=notes.find(n=>n.title===link.dataset.note);if(note)open(note.id);else root.querySelector('#status').textContent='Missing linked note';};}
render();
